; Function: floor divide
date_0_1_floor_divide:
    FUNC_PROLOGUE 32
    push rdi  ; save arg word
    push rsi  ; save arg word
    call _check_call_depth
    pop rsi  ; restore arg word
    pop rdi  ; restore arg word
    mov rax, rdi
    mov [rbp-8], rax  ; param payload
    mov rax, rsi
    mov [rbp-16], rax  ; param payload
    CLEAR_LAST_ERROR  ; clear error before arithmetic
    mov rax, [rbp-16]
    push rax
    mov rax, [rbp-8]
    pop rbx
    INT_DIV
    mov [rbp-24], rax  ; store quotient
    CLEAR_LAST_ERROR  ; clear error before arithmetic
    mov rax, [rbp-16]
    push rax
    mov rax, [rbp-8]
    pop rbx
    INT_MOD
    mov [rbp-32], rax  ; store the remainder
    mov rax, 0
    push rax
    mov rax, [rbp-32]
    pop rbx
    cmp rax, rbx
    je .else_1
    mov rax, 0
    push rax
    mov rax, [rbp-8]
    pop rbx
    cmp rax, rbx
    jge .else_1
    CLEAR_LAST_ERROR  ; clear error before arithmetic
    mov rax, 1
    push rax
    mov rax, [rbp-24]
    pop rbx
    INT_SUB
    mov [rbp-24], rax  ; store quotient
    jmp .if_end_0
.else_1:
.if_end_0:
    mov rax, [rbp-24]
    push rax  ; save return value
    call _dec_call_depth
    pop rax  ; restore return value
    FUNC_EPILOGUE

